   388→<script>
   389→// ── Config persistence ─────────────────────────────────────────────────────
   390→
   391→const LS_REPO  = 'org_dash_repo';
   392→const LS_TOKEN = 'org_dash_token';
   393→
   394→const $ = id => document.getElementById(id);
   395→
   396→function loadConfig() {
   397→  $('inp-repo').value  = localStorage.getItem(LS_REPO)  || 'sluna-wq/agentic-org-v2';
   398→  $('inp-token').value = localStorage.getItem(LS_TOKEN) || '';
   399→}
   400→
   401→function saveConfig() {
   402→  localStorage.setItem(LS_REPO,  $('inp-repo').value.trim());
   403→  localStorage.setItem(LS_TOKEN, $('inp-token').value.trim());
   404→}
   405→
   406→function clearConfig() {
   407→  localStorage.removeItem(LS_REPO);
   408→  localStorage.removeItem(LS_TOKEN);
   409→  $('inp-repo').value  = '';
   410→  $('inp-token').value = '';
   411→  $('site-header').style.display   = 'none';
   412→  $('main-content').style.display  = 'none';
   413→  showError('');
   414→}
   415→
   416→// ── GitHub API ────────────────────────────────────────────────────────────
   417→
   418→function apiHeaders(token) {
   419→  const h = { 'Accept': 'application/vnd.github.v3+json' };
   420→  if (token) h['Authorization'] = `Bearer ${token}`;
   421→  return h;
   422→}
   423→
   424→async function apiFetch(url, token) {
   425→  const res = await fetch(url, { headers: apiHeaders(token) });
   426→  if (!res.ok) {
   427→    const body = await res.json().catch(() => ({}));
   428→    const msg = body.message || res.statusText;
   429→    if (res.status === 403 || res.status === 429) {
   430→      const reset = res.headers.get('x-ratelimit-reset');
   431→      const when  = reset ? ` Resets at ${new Date(reset * 1000).toLocaleTimeString()}.` : '';
   432→      throw new Error(`Rate limit exceeded.${when} Supply a GitHub PAT for 5000 req/hr.`);
   433→    }
   434→    if (res.status === 404) throw new Error(`Not found: ${url}. Check owner/repo.`);
   435→    throw new Error(`GitHub API error ${res.status}: ${msg}`);
   436→  }
   437→  return res.json();
   438→}
   439→
   440→function b64decode(str) {
   441→  // GitHub base64 may have newlines
   442→  return atob(str.replace(/\n/g, ''));
   443→}
   444→
   445→// ── Data fetching ─────────────────────────────────────────────────────────
   446→
   447→async function fetchOrgData(repo, token) {
   448→  const base = `https://api.github.com/repos/${repo}`;
   449→
   450→  // 1. Get the recursive git tree to enumerate lead/ files
   451→  const tree = await apiFetch(`${base}/git/trees/main?recursive=1`, token);
   452→  const items = tree.tree || [];
   453→
   454→  // Identify blobs we want
   455→  const wantPaths = new Set(['lead/state.md', 'lead/decisions.md']);
   456→  const taskFiles = {};  // { 'task-XXX': { statusSha, packageSha } }
   457→
   458→  for (const item of items) {
   459→    if (item.type !== 'blob') continue;
   460→    const p = item.path;
   461→    if (wantPaths.has(p)) {
   462→      wantPaths.delete(p);
   463→    }
   464→    // lead/tasks/task-XXX/status.md or package.md
   465→    const m = p.match(/^lead\/tasks\/(task-\d+)\/(status|package)\.md$/);
   466→    if (m) {
   467→      const [, taskId, kind] = m;
   468→      if (!taskFiles[taskId]) taskFiles[taskId] = {};
   469→      taskFiles[taskId][kind + 'Sha'] = item.sha;
   470→    }
   471→  }
   472→
   473→  // Helper to fetch a blob by SHA
   474→  async function fetchBlob(sha) {
   475→    if (!sha) return null;
   476→    const blob = await apiFetch(`${base}/git/blobs/${sha}`, token);
   477→    return b64decode(blob.content);
   478→  }
   479→
   480→  // 2. Fetch all needed blobs in parallel
   481→  const stateShaItem    = items.find(i => i.path === 'lead/state.md');
   482→  const decisionShaItem = items.find(i => i.path === 'lead/decisions.md');
   483→
   484→  const [stateRaw, decisionsRaw] = await Promise.all([
   485→    fetchBlob(stateShaItem?.sha),
   486→    fetchBlob(decisionShaItem?.sha),
   487→  ]);
   488→
   489→  // Fetch task files
   490→  const taskIds = Object.keys(taskFiles).sort();
   491→  const taskData = {};
   492→  await Promise.all(taskIds.map(async (id) => {
   493→    const [statusRaw, packageRaw] = await Promise.all([
   494→      fetchBlob(taskFiles[id].statusSha),
   495→      fetchBlob(taskFiles[id].packageSha),
   496→    ]);
   497→    taskData[id] = { statusRaw, packageRaw };
   498→  }));
   499→
   500→  // 3. Fetch Actions runs
   501→  let runs = [];
   502→  try {
   503→    const runsData = await apiFetch(`${base}/actions/runs?per_page=10`, token);
   504→    runs = runsData.workflow_runs || [];
   505→  } catch (e) {
   506→    // Actions may not be enabled — not fatal
   507→    console.warn('Actions runs fetch failed:', e.message);
   508→  }
   509→
   510→  return { stateRaw, decisionsRaw, taskData, runs };
   511→}
   512→
   513→// ── Parsers ───────────────────────────────────────────────────────────────
   514→
   515→function parseMandate(stateMd) {
   516→  if (!stateMd) return '_No state.md found._';
   517→  const lines = stateMd.split('\n');
   518→  let inside = false;
   519→  const out = [];
   520→  for (const line of lines) {
   521→    if (!inside && /^## Mandate/.test(line)) { inside = true; continue; }
   522→    if (inside) {
   523→      if (/^##/.test(line) || /^---/.test(line)) break;
   524→      out.push(line);
   525→    }
   526→  }
   527→  return out.join('\n').trim() || '_Mandate section not found in state.md._';
   528→}
   529→
   530→function parseStatus(raw) {
   531→  const fields = {};
   532→  if (!raw) return fields;
   533→  for (const line of raw.split('\n')) {
   534→    const m = line.match(/^(\w+):\s*(.*)$/);
   535→    if (m) fields[m[1]] = m[2].trim();
   536→  }
   537→  return fields;
   538→}
   539→
   540→function parsePackageTitle(raw) {
   541→  if (!raw) return '(untitled)';
   542→  const m = raw.match(/^#\s+(.+)$/m);
   543→  return m ? m[1].trim() : '(untitled)';
   544→}
   545→
   546→function parseDecisions(raw) {
   547→  if (!raw) return [];
   548→  // Split on ## [ boundaries
   549→  const chunks = raw.split(/(?=^## \[)/m).filter(c => /^## \[/.test(c));
   550→  return chunks.slice(0, 10).map(chunk => {
   551→    const firstLine = chunk.split('\n')[0];
   552→    // ## [TIMESTAMP] task-XXX ACTION  or  ## [TIMESTAMP] LABEL
   553→    const hm = firstLine.match(/^## \[([^\]]+)\]\s+(.+)$/);
   554→    const ts     = hm ? hm[1] : '';
   555→    const action = hm ? hm[2].trim() : firstLine.replace(/^## /, '');
   556→    const body   = chunk.split('\n').slice(1).join('\n').trim();
   557→    return { ts, action, body };
   558→  });
   559→}
   560→
   561→// ── Rendering ─────────────────────────────────────────────────────────────
   562→
   563→const COLUMNS = ['planned', 'active', 'review', 'done'];
   564→const COLUMN_LABELS = {
   565→  planned: 'Planned',
   566→  active:  'Active',
   567→  review:  'Review',
   568→  done:    'Done',
   569→};
   570→
   571→// Map status field values to board columns
   572→function statusToColumn(status) {
   573→  if (!status) return 'planned';
   574→  if (['assigned', 'in_progress', 'changes_requested'].includes(status)) return 'active';
   575→  if (status === 'review') return 'review';
   576→  if (['accepted', 'discarded'].includes(status)) return 'done';
   577→  return 'planned';
   578→}
   579→
   580→function renderBadge(status) {
   581→  const label = status || 'unknown';
   582→  return `<span class="badge badge-${label}">${label.replace(/_/g, ' ')}</span>`;
   583→}
   584→
   585→function renderTaskBoard(taskData) {
   586→  const cols = { planned: [], active: [], review: [], done: [] };
   587→  let total = 0;
   588→
   589→  for (const [id, { statusRaw, packageRaw }] of Object.entries(taskData)) {
   590→    const s = parseStatus(statusRaw);
   591→    const title = parsePackageTitle(packageRaw);
   592→    const col = statusToColumn(s.status);
   593→    cols[col].push({ id, title, status: s.status, branch: s.branch, pr: s.pr });
   594→    total++;
   595→  }
   596→
   597→  $('task-count').textContent = total;
   598→
   599→  const board = $('task-board');
   600→  board.innerHTML = '';
   601→
   602→  for (const col of COLUMNS) {
   603→    const tasks = cols[col];
   604→    const colEl = document.createElement('div');
   605→    colEl.className = 'column';
   606→    colEl.innerHTML = `
   607→      <div class="column-header">
   608→        ${COLUMN_LABELS[col]}
   609→        <span class="count">${tasks.length}</span>
   610→      </div>
   611→    `;
   612→
   613→    if (tasks.length === 0) {
   614→      const empty = document.createElement('div');
   615→      empty.className = 'empty-col';
   616→      empty.textContent = 'none';
   617→      colEl.appendChild(empty);
   618→    } else {
   619→      for (const t of tasks) {
   620→        const card = document.createElement('div');
   621→        card.className = 'task-card';
   622→        card.innerHTML = `
   623→          <div class="task-meta">
   624→            <span class="task-id">${t.id}</span>
   625→            ${renderBadge(t.status)}
   626→            ${t.pr ? `<a href="https://github.com/${$('inp-repo').value.trim()}/pull/${t.pr}" target="_blank" style="font-size:11px">PR #${t.pr}</a>` : ''}
   627→          </div>
   628→          <div class="task-title">${escHtml(t.title)}</div>
   629→          ${t.branch ? `<div class="task-branch">${escHtml(t.branch)}</div>` : ''}
   630→        `;
   631→        colEl.appendChild(card);
   632→      }
   633→    }
   634→
   635→    board.appendChild(colEl);
   636→  }
   637→}
   638→
   639→function renderDecisions(decisions) {
   640→  $('decision-count').textContent = decisions.length;
   641→  const feed = $('decisions-feed');
   642→  feed.innerHTML = '';
   643→
   644→  if (!decisions.length) {
   645→    feed.innerHTML = '<span style="color:var(--muted);font-size:12px">No decisions found.</span>';
   646→    return;
   647→  }
   648→
   649→  decisions.forEach((d, i) => {
   650→    const entry = document.createElement('div');
   651→    entry.className = 'decision-entry';
   652→    const bodyHtml = d.body
   653→      ? marked.parse(d.body)
   654→      : '';
   655→    entry.innerHTML = `
   656→      <div class="decision-header">
   657→        <span class="decision-ts">${escHtml(d.ts)}</span>
   658→        <span class="decision-action">${escHtml(d.action)}</span>
   659→      </div>
   660→      ${bodyHtml ? `<div class="decision-body">${bodyHtml}</div>` : ''}
   661→      ${i < decisions.length - 1 ? '<hr class="divider" />' : ''}
   662→    `;
   663→    feed.appendChild(entry);
   664→  });
   665→}
   666→
   667→function fmtDuration(startedAt, updatedAt) {
   668→  if (!startedAt || !updatedAt) return '';
   669→  const secs = Math.round((new Date(updatedAt) - new Date(startedAt)) / 1000);
   670→  if (secs < 60) return `${secs}s`;
   671→  if (secs < 3600) return `${Math.floor(secs / 60)}m ${secs % 60}s`;
   672→  return `${Math.floor(secs / 3600)}h ${Math.floor((secs % 3600) / 60)}m`;
   673→}
   674→
   675→function renderCycles(runs) {
   676→  $('cycle-count').textContent = runs.length;
   677→  const timeline = $('cycle-timeline');
   678→  timeline.innerHTML = '';
   679→
   680→  if (!runs.length) {
   681→    timeline.innerHTML = '<span style="color:var(--muted);font-size:12px">No workflow runs found.</span>';
   682→    return;
   683→  }
   684→
   685→  for (const run of runs) {
   686→    const status  = run.conclusion || run.status || 'unknown';
   687→    const dur     = fmtDuration(run.run_started_at, run.updated_at);
   688→    const date    = run.run_started_at
   689→      ? new Date(run.run_started_at).toLocaleDateString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })
   690→      : '';
   691→
   692→    const entry = document.createElement('div');
   693→    entry.className = 'run-entry';
   694→    entry.innerHTML = `
   695→      <span class="run-num">#${run.run_number}</span>
   696→      <span class="run-name" title="${escHtml(run.name || '')}">
   697→        <a href="${escHtml(run.html_url)}" target="_blank">${escHtml(run.name || run.event || 'run')}</a>
   698→      </span>
   699→      ${renderBadge(status)}
   700→      <span class="run-duration" title="${date}">${dur || date}</span>
   701→    `;
   702→    timeline.appendChild(entry);
   703→  }
   704→}
   705→
   706→function renderMandate(stateRaw) {
   707→  const md = parseMandate(stateRaw);
   708→  $('mandate-body').innerHTML = marked.parse(md);
   709→}
   710→
   711→// ── Utilities ─────────────────────────────────────────────────────────────
   712→
   713→function escHtml(str) {
   714→  return (str || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
   715→}
   716→
   717→function showError(msg) {
   718→  const el = $('error-msg');
   719→  if (msg) {
   720→    el.style.display = 'block';
   721→    el.innerHTML = `<strong>Error:</strong> ${escHtml(msg)}`;
   722→  } else {
   723→    el.style.display = 'none';
   724→    el.innerHTML = '';
   725→  }
   726→}
   727→
   728→function setLoading(on) {
   729→  $('loading').style.display = on ? 'flex' : 'none';
   730→  $('btn-load').disabled    = on;
   731→  $('btn-refresh').disabled = on;
   732→}
   733→
   734→// ── Main load ─────────────────────────────────────────────────────────────
   735→
   736→async function loadDashboard() {
   737→  const repo  = $('inp-repo').value.trim();
   738→  const token = $('inp-token').value.trim();
   739→
   740→  if (!repo) {
   741→    showError('Please enter a GitHub repo (owner/repo).');
   742→    return;
   743→  }
   744→  if (!/^[\w.-]+\/[\w.-]+$/.test(repo)) {
   745→    showError('Repo must be in the format owner/repo.');
   746→    return;
   747→  }
   748→
   749→  saveConfig();
   750→  showError('');
   751→  setLoading(true);
   752→  $('main-content').style.display = 'none';
   753→
   754→  try {
   755→    const data = await fetchOrgData(repo, token);
   756→
   757→    renderMandate(data.stateRaw);
   758→    renderTaskBoard(data.taskData);
   759→    renderDecisions(parseDecisions(data.decisionsRaw));
   760→    renderCycles(data.runs);
   761→
   762→    $('header-repo').textContent = repo;
   763→    $('site-header').style.display   = 'flex';
   764→    $('main-content').style.display  = 'block';
   765→    $('last-updated').textContent = `Updated ${new Date().toLocaleTimeString()}`;
   766→  } catch (err) {
   767→    showError(err.message);
   768→  } finally {
   769→    setLoading(false);
   770→  }
   771→}
   772→
   773→// ── Event wiring ──────────────────────────────────────────────────────────
   774→
   775→$('btn-load').addEventListener('click', loadDashboard);
   776→$('btn-refresh').addEventListener('click', loadDashboard);
   777→$('btn-clear').addEventListener('click', clearConfig);
   778→
   779→$('inp-repo').addEventListener('keydown', e => { if (e.key === 'Enter') loadDashboard(); });
   780→$('inp-token').addEventListener('keydown', e => { if (e.key === 'Enter') loadDashboard(); });
   781→
   782→// Auto-load if config is saved
   783→loadConfig();
   784→if ($('inp-repo').value) loadDashboard();
   785→</script>
   786→</body>
   787→</html>
